<script lang="ts">
	import { goto } from '$app/navigation'; import { login } from '$lib/api/auth'; import { auth } from '$lib/stores/auth.svelte'; import Button from '$lib/components/ui/Button.svelte'; import Card from '$lib/components/ui/Card.svelte'; import Input from '$lib/components/ui/Input.svelte'; import Alert from '$lib/components/ui/Alert.svelte'; let email = $state(''); let password = $state(''); let error = $state(''); let saving = $state(false);
	async function submit() { error = ''; saving = true; try { const session = await login(email, password); auth.setSession(session.accessToken, session.refreshToken, session.user); goto('/'); } catch (reason) { error = reason instanceof Error ? reason.message : 'Unable to log in.'; } finally { saving = false; } }
</script>
<div class="mx-auto max-w-md"><Card><form class="space-y-4" onsubmit={(event) => { event.preventDefault(); submit(); }}><div><h1 class="text-xl font-semibold">Log in</h1><p class="text-sm text-slate-600">Use your booking-system account.</p></div>{#if error}<Alert>{error}</Alert>{/if}<label class="block text-sm font-medium">Email <Input bind:value={email} type="email" required /></label><label class="block text-sm font-medium">Password <Input bind:value={password} type="password" minlength={8} required /></label><Button type="submit" disabled={saving}>{saving ? 'Logging in…' : 'Log in'}</Button><p class="text-sm">New here? <a class="text-cyan-800 underline" href="/register">Create an account</a>.</p></form></Card></div>
